  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	import java.util.ArrayList;
  9	import java.util.List;
 10	
 11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 12	public final class ReservationService {
 13	
 14	    static final String HOTEL_NAME = "Pousada Maré Alta";
 15	
 16	    private final Rooms rooms;
 17	    private final ReservationStore store;
 18	    private final PriceCalculator priceCalculator;
 19	    private final EmailSender emailSender;
 20	    private final List<ReservationEventListener> listeners = new ArrayList<>();
 21	
 22	    public ReservationService(
 23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 24	        this.rooms = rooms;
 25	        this.store = store;
 26	        this.priceCalculator = priceCalculator;
 27	        this.emailSender = emailSender;
 28	    }
 29	
 30	    public void addListener(ReservationEventListener listener) {
 31	        listeners.add(listener);
 32	    }
 33	
 34	    public synchronized Reservation create(NewReservation request) {
 35	        if (!request.checkOut().isAfter(request.checkIn())) {
 36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 37	        }
 38	        if (request.guests() < 1) {
 39	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 40	        }
 41	        Room room = rooms.find(request.roomNumber())
 42	                .orElseThrow(() -> new HotelException(
 43	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 44	        if (request.guests() > room.capacity()) {
 45	            throw new HotelException(
 46	                    ErrorCode.CAPACITY_EXCEEDED,
 47	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 48	        }
 49	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 50	            throw new HotelException(
 51	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 52	        }
 53	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 54	        return store.add(request, price);
 55	    }
 56	
 57	    public Reservation find(long reservationId) {
 58	        return store.find(reservationId)
 59	                .orElseThrow(() -> new HotelException(
 60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 61	    }
 62	
 63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 64	    public synchronized Reservation confirm(long reservationId) {
 65	        Reservation reservation = find(reservationId);
 66	        if (reservation.status() != ReservationStatus.PENDING) {
 67	            throw notAllowed(reservation, "confirm");
 68	        }
 69	        reservation.confirmPayment();
 70	        store.update(reservation);
 71	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 72	        emailSender.send(
 73	                reservation.guest().email(),
 74	                "Reserva confirmada - " + HOTEL_NAME,
 75	                confirmationEmailBody(reservation, receipt));
 76	        notifyListeners(listener -> listener.onReservationConfirmed(reservation));
 77	        return reservation;
 78	    }
 79	
 80	    /**
 81	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 82	     * reservation was never paid, so nothing comes back).
 83	     */
 84	    public synchronized Reservation cancel(long reservationId) {
 85	        Reservation reservation = find(reservationId);
 86	        if (reservation.status() != ReservationStatus.PENDING
 87	                && reservation.status() != ReservationStatus.CONFIRMED) {
 88	            throw notAllowed(reservation, "cancel");
 89	        }
 90	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
 91	        BigDecimal refund = switch (reservation.ratePlan()) {
 92	            case STANDARD -> reservation.amountPaid();
 93	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 94	        };
 95	        reservation.cancel(refund);
 96	        store.update(reservation);
 97	        if (wasConfirmed) {
 98	            notifyListeners(listener -> listener.onReservationCancelled(reservation));
 99	        }
100	        return reservation;
101	    }
102	
103	    public synchronized Reservation checkIn(long reservationId) {
104	        Reservation reservation = find(reservationId);
105	        if (reservation.status() != ReservationStatus.CONFIRMED) {
106	            throw notAllowed(reservation, "check in");
107	        }
108	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
109	        store.update(reservation);
110	        return reservation;
111	    }
112	
113	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
114	    public synchronized ReservationReceipt checkOut(long reservationId) {
115	        Reservation reservation = find(reservationId);
116	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
117	            throw notAllowed(reservation, "check out");
118	        }
119	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
120	        store.update(reservation);
121	        return new ReservationReceipt(reservation, roomOf(reservation));
122	    }
123	
124	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
125	    public ReservationReceipt receiptCopy(long reservationId) {
126	        Reservation reservation = find(reservationId);
127	        if (!reservation.isPaid()) {
128	            throw notAllowed(reservation, "issue a receipt for");
129	        }
130	        return new ReservationReceipt(reservation, roomOf(reservation));
131	    }
132	
133	    private Room roomOf(Reservation reservation) {
134	        return rooms.find(reservation.roomNumber()).orElseThrow();
135	    }
136	
137	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
138	        return "Olá, " + reservation.guest().name() + "!\n\n"
139	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
140	                + receipt.text() + "\n"
141	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
142	                + "Até breve!\n";
143	    }
144	
145	    private static HotelException notAllowed(Reservation reservation, String operation) {
146	        return new HotelException(
147	                ErrorCode.OPERATION_NOT_ALLOWED,
148	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
149	    }
150	
151	    private void notifyListeners(java.util.function.Consumer<ReservationEventListener> notification) {
152	        listeners.forEach(notification);
153	    }
154	}
